#include <bits/stdc++.h>
using namespace std;
int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);
    vector<pair<int,int>> ops;
    auto do_op=[&](int x,int y){
        ops.push_back({x,y});
        vector<int> np;
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p=np;
    };
    for(int i=0;i<n-1;i++){
        int j=-1;
        for(int k=i;k<n;k++) if(p[k]==i+1){j=k;break;}
        if(j==i) continue;
        // Move element from position j to position 0
        if(j==1){
            // x=1,y=1 if n>2: [p[n-1]][p[1]..p[n-2]][p[0]] -> p[1] goes to pos n-1
            // Use x=2,y=n-2 requires 2+(n-2)<n -> false. Use x=1,y=n-1 requires n<n false.
            // Rotate: x=1,y=1 -> element at j=1 goes to position... p[1] is in middle[1..n-2], stays at same relative pos = index 1. Hmm.
            // x=j+1=2, but need y: 2+y<n => y<=n-3. do_op(2,n-2-1+1)... just do y=n-j-1=n-2 needs 1+n-2<n -> false
            // Bring to 0: need suffix to start at j. y=n-j=n-1, x=1: 1+n-1=n not <n. 
            // So first move j=1 somewhere else with a random op
            if(n>2) do_op(1,1);
            i--; continue;
        }
        if(j>1){ do_op(1,n-j); } // now at position 0
        // Move from position 0 to position i
        if(i==0) continue;
        if(i==1){ do_op(n-1,1); }
        else { do_op(n-i,1); }
    }
    printf("%d\n",(int)ops.size());
    for(auto&[a,b]:ops) printf("%d %d\n",a,b);
}
